import { 
  View, 
  Text, 
  KeyboardAvoidingView, 
  Platform, 
  SafeAreaView, 
  ScrollView{{#if (eq styling "stylesheet")}}, 
  StyleSheet{{/if}} 
} from 'react-native';
import { Link } from 'expo-router';
{{#if (eq icons "lucide")}}
import { ArrowLeft } from 'lucide-react-native';
{{/if}}
import { ForgotPasswordForm } from '../../components/ForgotPasswordForm';

export default function ForgotPasswordScreen() {
  return (
    <SafeAreaView {{#if (eq styling "nativewind")}}className="flex-1 bg-white"{{else}}style={styles.safeArea}{{/if}}>
      <KeyboardAvoidingView
        behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
        {{#if (eq styling "nativewind")}}className="flex-1"{{else}}style={styles.flex1}{{/if}}
      >
        <ScrollView
          contentContainerStyle={styles.scrollContent}
          keyboardShouldPersistTaps="handled"
        >
          {{#if (eq icons "lucide")}}
          <Link href="/login" {{#if (eq styling "nativewind")}}className="mb-6"{{else}}style={styles.backButton}{{/if}}>
            <ArrowLeft size={24} color="#111827" />
          </Link>
          {{/if}}

          <View {{#if (eq styling "nativewind")}}className="mb-8"{{else}}style={styles.header}{{/if}}>
            <Text {{#if (eq styling "nativewind")}}className="text-3xl font-bold text-gray-900"{{else}}style={styles.title}{{/if}}>
              Reset password
            </Text>
            <Text {{#if (eq styling "nativewind")}}className="mt-2 text-base text-gray-600"{{else}}style={styles.subtitle}{{/if}}>
              Enter your email and we'll send you a link to reset your password.
            </Text>
          </View>

          <ForgotPasswordForm />
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

