import { useState } from "react";
import { Controller, useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Text, View } from "react-native";
import { Mail } from "lucide-react-native";
import { Input } from "../components/ui/input";
import { Button } from "../components/ui/button";

const schema = z.object({
  email: z.string().min(1, "Email is required").email("Enter a valid email"),
});

type FormData = z.infer<typeof schema>;

export function ForgotPasswordForm() {
  const [sent, setSent] = useState(false);
  const {
    control,
    handleSubmit,
    formState: { errors, isSubmitting },
  } = useForm<FormData>({
    resolver: zodResolver(schema),
    defaultValues: { email: "" },
  });

  const onSubmit = (data: FormData) => {
    console.log(data);
    setSent(true);
  };

  if (sent) {
    return (
      <View className="gap-3">
        <View className="items-center rounded-xl bg-green-50 px-4 py-4">
          <Text className="text-base font-medium text-green-700">
            Check your inbox! We sent a reset link to your email.
          </Text>
        </View>
      </View>
    );
  }

  return (
    <View className="gap-4">
      <View>
        <View className="flex-row items-center gap-3">
          <Mail size={20} className="text-muted-foreground" />
          <Controller
            control={control}
            name="email"
            render={({ field: { onChange, onBlur, value } }) => (
              <Input
                placeholder="Email"
                autoCapitalize="none"
                keyboardType="email-address"
                className="flex-1"
                value={value}
                onChangeText={onChange}
                onBlur={onBlur}
              />
            )}
          />
        </View>
        {errors.email && (
          <Text className="mt-1 text-sm text-destructive">{errors.email.message}</Text>
        )}
      </View>

      <Button
        onPress={handleSubmit(onSubmit)}
        disabled={isSubmitting}
        className="mt-2"
        size="lg"
      >
        {isSubmitting ? "Sending..." : "Send Reset Link"}
      </Button>
    </View>
  );
}
